//@version=1
// 21-155 Inverse FVG Retest + strong close · NQ 60m · all sessions
// FX Replay (FXR Script) indicator generated by `python -m confluence.cli fxr-script 21-155`.
//
// Put it on an NQ 60-minute chart. It marks every setup, simulates the trade the
// backtest would take (entry, stop, exit) and keeps a running tally in R and dollars.
// Take the marked trades yourself with FX Replay's order tools to journal them.
//
// Backtest, Sep 2018 - Sep 2026 on the Nasdaq-100 CFD: 2,890 trades, 33% win rate, +0.06R per trade after costs.
// The script only sees bars, not the 1-minute path inside them, so a few trades
// can differ from the backtest (a stop and the fill in the same bar, trailing stops).

// ------------------------------------------------------------------ strategy constants
const S = {
  sid: '21-155',
  tf: 60,                     // chart timeframe the rules were tested on (minutes)
  signal: 'ifvgRetest',           // setup detector, below
  entry: 'market',             // 'market' = next bar open, 'stop' = 1 tick beyond the signal bar, valid 3 bars
  stopAtr: 1.0,           // initial stop = entry -/+ stopAtr x ATR(14) of the signal bar
  trail: true,               // after +1R, trail 2 x ATR(14) behind the best price at each bar close
  sesFrom: 18 * 60 + 5,           // signal bar must CLOSE between these New York times (hh*60+mm)
  sesTo: 15 * 60 + 30,
  flatAt: 16 * 60 + 5,               // flat at this New York time
  maxPerDay: 4,
  warmup: 300,                    // no setups in the first 300 bars while ATR, swings and averages settle
  atrLen: 14,
  swingAtr: 3.0,                  // a swing high/low is confirmed after a 3 x ATR reversal
  minStopAtr: 0.3,                // stops never tighter than 0.3 ATR ...
  minStopCosts: 4.0,              // ... or 4 round-trip costs
};

init = () => {
  indicator({ onMainPanel: true, format: 'inherit' });
  input.float('Risk per trade ($)', 500, 'riskUsd', 10, 10000, 10);
  input.float('Point value per contract ($)', 2, 'pointValue', 0.1, 100, 0.1);
  input.float('Round-trip cost (points)', 1.11, 'costPts', 0, 20, 0.01);
  input.float('Tick size', 0.25, 'tick', 0.0001, 10, 0.0001);
  input.bool('Take shorts', true, 'shorts');
  input.bool('Draw trades', true, 'draw');
};

// ------------------------------------------------------------------ New York clock
const DAY = 86400000;
const toMs = (t) => (t < 1e12 ? t * 1000 : t);
const nthSunday = (y, m, n) => {             // UTC ms of the n-th Sunday of month m (0-based)
  const first = new Date(Date.UTC(y, m, 1)).getUTCDay();
  return Date.UTC(y, m, 1 + ((7 - first) % 7) + 7 * (n - 1));
};
const nyOffsetH = (ms) => {                  // US daylight time: 2nd Sun Mar 07:00 UTC .. 1st Sun Nov 06:00 UTC
  const y = new Date(ms).getUTCFullYear();
  const a = nthSunday(y, 2, 2) + 7 * 3600000, b = nthSunday(y, 10, 1) + 6 * 3600000;
  return ms >= a && ms < b ? -4 : -5;
};
// trading day rolls at 18:00 New York; tdm = minutes since 18:00
const clockOf = (ms) => {
  const local = ms + nyOffsetH(ms) * 3600000 + 6 * 3600000;
  return { day: Math.floor(local / DAY), tdm: Math.floor((((local % DAY) + DAY) % DAY) / 60000) };
};
const tdmOf = (hhmm) => (((hhmm - 18 * 60) % 1440) + 1440) % 1440;

// ------------------------------------------------------------------ state
const B = { t: [], o: [], h: [], l: [], c: [], day: [], tdmo: [], tdmc: [] };
const TR = [], ATR = [], ATRZ = [];
const piv = [];                              // {p, i, type: 1 high / -1 low, conf}
let zz = { d: 0, hi: -Infinity, hiI: 0, lo: Infinity, loI: 0 };
let bear = null, bull = null;                // last fair-value gaps {top, bot, j}
let pending = null, pos = null;
let curDay = null, dayCount = 0;
let lastSeen = null;
const trades = [];
let summaryId = null;
let I = {};                                  // inputs

// ------------------------------------------------------------------ indicators
const updateIndicators = (k) => {
  const h = B.h[k], l = B.l[k], c1 = k > 0 ? B.c[k - 1] : NaN;
  TR[k] = k === 0 ? h - l : Math.max(h - l, Math.abs(h - c1), Math.abs(l - c1));
  const n = S.atrLen;
  if (k < n - 1) ATR[k] = NaN;
  else if (k === n - 1) { let s = 0; for (let j = 0; j < n; j++) s += TR[j]; ATR[k] = s / n; }
  else ATR[k] = (ATR[k - 1] * (n - 1) + TR[k]) / n;
  ATRZ[k] = isNaN(ATR[k]) ? 0 : ATR[k];
  // zigzag swings, confirmed on the bar where the reversal happens
  const a = ATR[k];
  if (a > 0) {
    if (h > zz.hi) { zz.hi = h; zz.hiI = k; }
    if (l < zz.lo) { zz.lo = l; zz.loI = k; }
    if (zz.d >= 0 && zz.hi - l >= S.swingAtr * a && (zz.d === 1 || zz.hiI > zz.loI)) {
      piv.push({ p: zz.hi, i: zz.hiI, type: 1, conf: k });
      zz.d = -1; zz.lo = l; zz.loI = k;
    } else if (zz.d <= 0 && h - zz.lo >= S.swingAtr * a && (zz.d === -1 || zz.loI > zz.hiI)) {
      piv.push({ p: zz.lo, i: zz.loI, type: -1, conf: k });
      zz.d = 1; zz.hi = h; zz.hiI = k;
    }
  }
};
const smaZ = (k, n) => {
  if (k < n - 1) return NaN;
  let s = 0;
  for (let j = k - n + 1; j <= k; j++) s += ATRZ[j];
  return s / n;
};

// ------------------------------------------------------------------ setups (long, short)
const SIGNALS = {
  // 36-221: swing low retested as support + bullish engulfing + ATR below its 100-bar average
  swingEngulf: (k) => {
    if (k < 1) return [false, false];
    const o = B.o[k], h = B.h[k], l = B.l[k], c = B.c[k], o1 = B.o[k - 1], c1 = B.c[k - 1], a = ATR[k];
    const calm = ATR[k] < smaZ(k, 100);
    const engUp = c1 < o1 && c > o && c >= o1 && o <= c1;
    const engDn = c1 > o1 && c < o && c <= o1 && o >= c1;
    let sup = false, res = false, nl = 0, nh = 0;
    if (piv.length >= 2) {
      for (let j = piv.length - 1; j >= 0 && (nl < 4 || nh < 4); j--) {
        const pv = piv[j];
        if (pv.type === -1 && nl < 4) {
          nl++;
          if (pv.p < c && Math.abs(l - pv.p) <= 0.25 * a && c > pv.p) sup = true;
        } else if (pv.type === 1 && nh < 4) {
          nh++;
          if (pv.p > c && Math.abs(h - pv.p) <= 0.25 * a && c < pv.p) res = true;
        }
      }
    }
    return [sup && engUp && calm, res && engDn && calm];
  },
  // 21-155: bar closes back through a fair-value gap from the last 20 bars + close beyond the
  // prior bar's extreme + close in the outer 30% of its range
  ifvgRetest: (k) => {
    if (k < 2) return [false, false];
    const o = B.o[k], h = B.h[k], l = B.l[k], c = B.c[k];
    const r = Math.max(h - l, 1e-12);
    const okGap = (g) => g !== null && g.j <= k - 1 && (k - 1) - g.j <= 20;
    const up = okGap(bear) && l <= bear.top && c > bear.bot && c > bear.top && c > B.h[k - 1] && c > o && (c - l) >= 0.7 * r;
    const dn = okGap(bull) && h >= bull.bot && c < bull.top && c < bull.bot && c < B.l[k - 1] && c < o && (h - c) >= 0.7 * r;
    // record gaps formed on this bar (usable from the next bar)
    const a = ATR[k], h2 = B.h[k - 2], l2 = B.l[k - 2];
    if (h < l2 && (l2 - h) > 0.1 * a) bear = { top: l2, bot: h, j: k };
    if (l > h2 && (l - h2) > 0.1 * a) bull = { top: l, bot: h2, j: k };
    return [up, dn];
  },
};

// ------------------------------------------------------------------ drawing
const draw = (tr) => {
  if (!I.draw) return;
  const win = tr.r > 0, col = win ? color.rgba(38, 166, 91, 0.95) : color.rgba(235, 64, 52, 0.95);
  trendLine(newPoint(tr.t0, tr.entry), newPoint(tr.t1, tr.exit),
    { linecolor: col, linewidth: 2, showLabel: true },
    `${S.sid} #${trades.length} ${tr.dir > 0 ? 'L' : 'S'} ${tr.r >= 0 ? '+' : ''}${tr.r.toFixed(2)}R`);
  trendLine(newPoint(tr.t0, tr.stop), newPoint(tr.t1, tr.stop),
    { linecolor: color.rgba(235, 64, 52, 0.6), linewidth: 1, linestyle: 2 });
};
const summary = (k) => {
  if (!I.draw) return;
  const n = trades.length, w = trades.filter((x) => x.r > 0).length;
  const tot = trades.reduce((s, x) => s + x.r, 0);
  const msg = `${S.sid}: ${n} trades, ${n ? Math.round((100 * w) / n) : 0}% win, ` +
    `${tot >= 0 ? '+' : ''}${tot.toFixed(1)}R = ${tot >= 0 ? '+' : '-'}$${Math.abs(Math.round(tot * I.riskUsd)).toLocaleString()} at $${I.riskUsd}/trade`;
  if (summaryId !== null && typeof deleteDrawingById === 'function') deleteDrawingById(summaryId);
  summaryId = text(B.t[k], B.h[k], { color: color.white, fillBackground: true,
    backgroundColor: color.rgba(20, 30, 48, 0.85), fontsize: 12, bold: true }, msg);
};

// ------------------------------------------------------------------ the trade simulation
const exitTdm = () => tdmOf(S.flatAt);
const closeTrade = (xp, k, why) => {
  const p = pos, cost = I.costPts;
  const r = ((xp - p.entry) * p.dir) / p.risk - cost / p.risk;
  const tr = { dir: p.dir, t0: B.t[p.fill], entry: p.entry, stop: p.stop0, t1: B.t[k], exit: xp, r, why,
               sig: B.t[p.sig], day: p.day, contracts: p.contracts };
  trades.push(tr);
  draw(tr);
  summary(k);
  pos = null;
};

const openTrade = (k, entry, pd) => {
  const a = pd.atr;
  let stop = entry - pd.dir * S.stopAtr * a;
  let risk = (entry - stop) * pd.dir;
  const floor = Math.max(S.minStopAtr * a, S.minStopCosts * I.costPts);
  if (!(risk >= floor)) { risk = floor; stop = entry - pd.dir * risk; }
  pos = { dir: pd.dir, entry, stop, stop0: stop, risk, best: entry, fill: k, sig: pd.sig, day: pd.day,
          trailing: false, contracts: Math.max(1, Math.round(I.riskUsd / (risk * I.pointValue))) };
  if (pd.day !== curDay) { curDay = pd.day; dayCount = 0; }
  dayCount++;
  if (I.draw) plot.shapes('Entry', entry, `${pd.dir > 0 ? 'BUY' : 'SELL'} ${pos.contracts}`, pd.dir > 0 ? 'rgba(38,166,91,0.95)' : 'rgba(235,64,52,0.95)',
    '#FFFFFF', pd.dir > 0 ? 'shape_arrow_up' : 'shape_arrow_down', pd.dir > 0 ? 'BelowBar' : 'AboveBar', 'small', -1);
};

// one bar of an open position; returns true if the trade closed in this bar
const manage = (k, fillBar) => {
  const p = pos, o = B.o[k], h = B.h[k], l = B.l[k];
  if (B.day[k] !== p.day) { closeTrade(B.c[k - 1], k - 1, 'day'); return true; }
  const ex = exitTdm();
  if (B.tdmo[k] >= ex || (B.tdmo[k] < ex && B.tdmc[k] > ex)) { closeTrade(o, k, 'session'); return true; }
  const sameAsFill = fillBar && S.entry !== 'market';
  // On the bar a stop order fills, the bar's other extreme may have come before the fill.
  // Assume the usual path: a green bar goes open-low-high-close, a red bar open-high-low-close.
  const beforeFill = sameAsFill && (p.dir > 0 ? B.c[k] >= o : B.c[k] <= o);
  if (beforeFill) {
    p.best = p.dir > 0 ? Math.max(p.best, h) : Math.min(p.best, l);
    return false;
  }
  if (p.dir > 0 && l <= p.stop) { closeTrade(sameAsFill || o > p.stop ? p.stop : o, k, p.trailing ? 'trail' : 'stop'); return true; }
  if (p.dir < 0 && h >= p.stop) { closeTrade(sameAsFill || o < p.stop ? p.stop : o, k, p.trailing ? 'trail' : 'stop'); return true; }
  p.best = p.dir > 0 ? Math.max(p.best, h) : Math.min(p.best, l);
  if (S.trail && (p.best - p.entry) * p.dir >= p.risk && ATR[k] > 0) {
    const ns = p.best - p.dir * 2 * ATR[k];
    if ((ns - p.stop) * p.dir > 0) { p.stop = ns; p.trailing = true; }
  }
  return false;
};

const onBar = (k) => {
  updateIndicators(k);
  const [L0, S0] = SIGNALS[S.signal](k);        // always run: it also tracks gaps
  const L = L0 && k >= S.warmup, Sh = S0 && I.shorts && k >= S.warmup;
  let evaluate = true;
  // pending orders
  if (pending) {
    const pd = pending;
    if (pd.kind === 'market') {
      pending = null;
      if (B.day[k] === pd.day && B.tdmo[k] < exitTdm()) {
        openTrade(k, B.o[k], pd);
        if (!manage(k, true)) evaluate = false;
      }
    } else {
      if (pd.alive && (B.day[k] !== pd.day || B.tdmo[k] >= exitTdm())) pd.alive = false;
      if (pd.alive && (pd.dir > 0 ? B.h[k] >= pd.px : B.l[k] <= pd.px)) {
        const entry = pd.dir > 0 ? Math.max(B.o[k], pd.px) : Math.min(B.o[k], pd.px);
        pending = null;
        openTrade(k, entry, pd);
        if (!manage(k, true)) evaluate = false;
      } else if (k >= pd.until) {
        pending = null;
      } else {
        evaluate = false;
      }
    }
  } else if (pos) {
    if (!manage(k, false)) evaluate = false;
  }
  if (!evaluate || pos || pending) return;
  // a new setup on this bar's close
  if (L === Sh) return;
  const tc = B.tdmc[k];
  if (tc < tdmOf(S.sesFrom) || tc > tdmOf(S.sesTo)) return;
  if (B.day[k] === curDay && dayCount >= S.maxPerDay) return;
  if (!(ATR[k] > 0)) return;
  const dir = L ? 1 : -1;
  const pd = { dir, sig: k, day: B.day[k], atr: ATR[k], kind: S.entry, alive: true, until: k + 3,
               px: dir > 0 ? B.h[k] + I.tick : B.l[k] - I.tick };
  pending = pd;
  if (I.draw) plot.shapes('Setup', B.c[k], S.entry === 'stop' ? `${dir > 0 ? 'buy stop' : 'sell stop'} ${pd.px.toFixed(2)}` : 'setup',
    dir > 0 ? 'rgba(38,166,91,0.6)' : 'rgba(235,64,52,0.6)', '#FFFFFF',
    dir > 0 ? 'shape_triangle_up' : 'shape_triangle_down', dir > 0 ? 'BelowBar' : 'AboveBar', 'tiny', -1);
};

// ------------------------------------------------------------------ bar feed
// Each bar is processed once, when the next bar appears (so only closed bars count).
onTick = (length, _moment, _, ta, inputs) => {
  I = inputs;
  const t0 = time(0);
  if (t0 === undefined || isNaN(t0) || t0 === lastSeen) return;
  const first = lastSeen === null;
  lastSeen = t0;
  if (first) return;
  const t = toMs(time(1));
  const o = openC(1), h = high(1), l = low(1), c = closeC(1);
  if ([o, h, l, c].some((v) => v === undefined || isNaN(v))) return;
  if (B.t.length && t <= B.t[B.t.length - 1]) return;
  const ck = clockOf(t);
  B.t.push(t); B.o.push(o); B.h.push(h); B.l.push(l); B.c.push(c);
  B.day.push(ck.day); B.tdmo.push(ck.tdm); B.tdmc.push(Math.min(ck.tdm + S.tf, 1440));
  onBar(B.t.length - 1);
};
